import java.util.*;
import java.io.*;

public class x111C {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int R = sc.nextInt();
        int C = sc.nextInt();
        if (R > C) {
            int t = R; R = C; C = t;
        }
        int full = (1 << R) - 1;
        int INF = 69;
        int size = 1 << R;
        // rolling DP: prev[mask1][mask2], cur[mask2][mask3]
        int[][] prev = new int[size][size];
        int[][] cur = new int[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(prev[i], INF);
            Arrays.fill(cur[i], INF);
        }
        // base: dp[0][0][mask] = 0
        for (int mask = 0; mask < size; mask++) {
            prev[0][mask] = 0;
        }
        for (int c = 1; c <= C; c++) {
            // reset cur
            for (int i = 0; i < size; i++) Arrays.fill(cur[i], INF);
            for (int mask2 = 0; mask2 < size; mask2++) {
                for (int mask3 = 0; mask3 < size; mask3++) {
                    int best = INF;
                    for (int mask1 = 0; mask1 < size; mask1++) {
                        if (prev[mask1][mask2] == INF) continue;
                        // check validity condition using bitwise operations
                        // cover: left neighbor (mask2 << 1), right neighbor (mask2 >> 1), mask1, mask3
                        int cover = ((mask2 << 1) & full) | (mask2 >> 1) | mask1 | mask3;
                        int zeros = (~mask2) & full;
                        if ((zeros & ~cover) == 0) {
                            int val = prev[mask1][mask2] + Integer.bitCount(mask1);
                            if (val < best) best = val;
                        }
                    }
                    cur[mask2][mask3] = best;
                }
            }
            // swap
            int[][] temp = prev;
            prev = cur;
            cur = temp;
        }
        int res = 0;
        for (int mask = 0; mask < size; mask++) {
            int val = prev[mask][0]; // dp[C][mask][0]
            if (val == INF) continue;
            res = Math.max(res, R * C - (val + Integer.bitCount(mask)));
        }
        System.out.println(res);
    }
}
